import json
import re
from typing import Dict, List, Tuple


def _parse_sections(text: str) -> List[Tuple[str, List[str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw_line in text.splitlines():
        header_match = re.match(r"^\s*\[([^\]]+)\]\s*$", raw_line)
        if header_match:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = header_match.group(1).strip()
            current_lines = []
            continue

        if current_id is None:
            continue

        line = raw_line.strip()
        if line:
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    return sections


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections = _parse_sections(text)
    node_order: List[str] = [node_id for node_id, _ in sections]
    nodes: Dict[str, Dict[str, str]] = {}
    edges: List[Dict[str, str]] = []

    for node_id, lines in sections:
        if not lines:
            nodes[node_id] = {"id": node_id, "text": "", "speaker": "", "type": "line"}
            continue

        is_choice = all(re.match(r"^\s*\d+\.\s+.+", line) for line in lines)
        if is_choice:
            nodes[node_id] = {"id": node_id, "text": "", "speaker": "", "type": "choice"}
            for line in lines:
                left, arrow, right = line.rpartition("->")
                if not arrow:
                    continue
                target = right.strip()
                left = left.strip()
                match = re.match(r"^\s*\d+\.\s*(.+)$", left)
                option_text = match.group(1).strip() if match else left
                edges.append({"from": node_id, "to": target, "text": option_text})
        else:
            # Treat as a single spoken line.
            line = lines[0]
            left, arrow, right = line.rpartition("->")
            if arrow:
                target = right.strip()
                left = left.strip()
            else:
                target = ""
                left = line.strip()

            speaker = ""
            text_value = left
            if ":" in left:
                speaker_part, text_part = left.split(":", 1)
                speaker = speaker_part.strip()
                text_value = text_part.strip()

            nodes[node_id] = {
                "id": node_id,
                "text": text_value,
                "speaker": speaker,
                "type": "line",
            }

            if target:
                edges.append({"from": node_id, "to": target, "text": ""})

            # Append any extra lines (if present) to the text.
            if len(lines) > 1:
                extras: List[str] = []
                for extra in lines[1:]:
                    extra_left, extra_arrow, _ = extra.rpartition("->")
                    extras.append(extra_left.strip() if extra_arrow else extra.strip())
                if extras:
                    nodes[node_id]["text"] = (nodes[node_id]["text"] + " " + " ".join(extras)).strip()

    # Add stub nodes for missing edge targets (e.g., End)
    for edge in edges:
        target = edge["to"]
        if target and target not in nodes:
            nodes[target] = {"id": target, "text": "", "speaker": "", "type": "line"}
            node_order.append(target)

    # Ensure all nodes are reachable from the first node
    reachable = set()
    if node_order:
        start = node_order[0]
        stack = [start]
        adjacency: Dict[str, List[str]] = {}
        for edge in edges:
            adjacency.setdefault(edge["from"], []).append(edge["to"])

        while stack:
            current = stack.pop()
            if current in reachable:
                continue
            reachable.add(current)
            for nxt in adjacency.get(current, []):
                if nxt not in reachable:
                    stack.append(nxt)

    # Filter nodes and edges to reachable set
    filtered_nodes = [nodes[nid] for nid in node_order if nid in reachable]
    filtered_edges = [edge for edge in edges if edge["from"] in reachable and edge["to"] in reachable]

    return {"nodes": filtered_nodes, "edges": filtered_edges}


def _graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [shape=box];"]

    # Nodes
    for node in graph["nodes"]:
        label_parts = [node["id"]]
        if node["type"] == "line":
            speaker = node.get("speaker", "")
            text = node.get("text", "")
            if speaker or text:
                label_parts.append(f"{speaker}: {text}".strip(": "))
        else:
            label_parts.append("(choice)")
        label = "\\n".join(label_parts)
        safe_label = label.replace("\\", "\\\\").replace("\"", "\\\"")
        safe_id = node["id"].replace("\\", "\\\\").replace("\"", "\\\"")
        lines.append(f"  \"{safe_id}\" [label=\"{safe_label}\"]; ")

    # Edges
    for edge in graph["edges"]:
        edge_label = edge.get("text", "") or ""
        safe_edge_label = edge_label.replace("\\", "\\\\").replace("\"", "\\\"")
        safe_from = edge["from"].replace("\\", "\\\\").replace("\"", "\\\"")
        safe_to = edge["to"].replace("\\", "\\\\").replace("\"", "\\\"")
        if safe_edge_label:
            lines.append(f"  \"{safe_from}\" -> \"{safe_to}\" [label=\"{safe_edge_label}\"]; ")
        else:
            lines.append(f"  \"{safe_from}\" -> \"{safe_to}\"; ")

    lines.append("}")
    return "\n".join(lines)


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    ids = {node["id"] for node in graph["nodes"]}
    if not graph["nodes"]:
        raise ValueError("Graph has no nodes")

    # Constraint: all edge targets must exist
    for edge in graph["edges"]:
        if edge["to"] not in ids:
            raise ValueError(f"Edge target missing: {edge['to']}")

    # Constraint: all nodes reachable from first
    start = graph["nodes"][0]["id"]
    adjacency: Dict[str, List[str]] = {}
    for edge in graph["edges"]:
        adjacency.setdefault(edge["from"], []).append(edge["to"])

    reachable = set()
    stack = [start]
    while stack:
        current = stack.pop()
        if current in reachable:
            continue
        reachable.add(current)
        for nxt in adjacency.get(current, []):
            if nxt not in reachable:
                stack.append(nxt)

    missing = ids - reachable
    if missing:
        raise ValueError(f"Unreachable nodes: {sorted(missing)}")


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)
    _validate_graph(graph)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)

    dot = _graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)


if __name__ == "__main__":
    main()
